import{_ as e,o as a,c as d,a2 as o}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"方案介绍","description":"","frontmatter":{},"headers":[],"relativePath":"app/list-page/style-extension/highlight-number-field-by-condition/solution-overview.md","filePath":"app/list-page/style-extension/highlight-number-field-by-condition/solution-overview.md"}'),r={name:"app/list-page/style-extension/highlight-number-field-by-condition/solution-overview.md"};function i(l,t,n,h,s,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="方案介绍" tabindex="-1">方案介绍 <a class="header-anchor" href="#方案介绍" aria-label="Permalink to &quot;方案介绍&quot;">​</a></h1><h2 id="方案概述" tabindex="-1">方案概述 <a class="header-anchor" href="#方案概述" aria-label="Permalink to &quot;方案概述&quot;">​</a></h2><p>本方案通过在列表页面（EntityList）中进行组件级扩展实现。在数值字段级别使用条件样式扩展属性，根据字段取值动态设置显示颜色或样式。通过事件绑定和渲染逻辑，实现列表页中数值字段按数值区间高亮显示，使关键数据一目了然，提升用户在列表页的关注效率。</p><h2 id="扩展组件" tabindex="-1">扩展组件 <a class="header-anchor" href="#扩展组件" aria-label="Permalink to &quot;扩展组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>终端</th><th>扩展对象</th><th>扩展页面</th><th>扩展区域</th><th>扩展组件</th><th>扩展功能</th></tr></thead><tbody><tr><td>网页端/移动端</td><td>商机</td><td>一级列表页</td><td>数据列表</td><td>字段值</td><td>根据字段值所属的数据范围，动态以不同颜色进行区分展示</td></tr></tbody></table><h2 id="功能设计" tabindex="-1">功能设计 <a class="header-anchor" href="#功能设计" aria-label="Permalink to &quot;功能设计&quot;">​</a></h2><ol><li><p><strong>触发时机</strong></p><p>在字段渲染前执行条件判断并应用相应样式。</p></li><li><p><strong>条件判断逻辑</strong></p><ul><li><p><strong>获取字段值</strong></p><p>遍历列表中每行记录，获取“商机金额”字段值。</p></li><li><p><strong>数值区间匹配</strong></p><p>根据预设规则判断字段所属区间，如下：</p><p>金额 &gt; 1000 万：红色高亮</p><p>金额在 500 万 - 1000 万：橙色高亮</p><p>金额 &lt; 500 万：默认样式（黑色）</p></li></ul></li></ol><h2 id="使用的-nex-扩展能力" tabindex="-1">使用的 NEX 扩展能力 <a class="header-anchor" href="#使用的-nex-扩展能力" aria-label="Permalink to &quot;使用的 NEX 扩展能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能点</th><th>扩展能力类别</th><th>属性/函数/事件</th><th>说明</th><th>示例值/使用方式</th></tr></thead><tbody><tr><td>字段渲染前执行判断逻辑</td><td>事件绑定</td><td>事件：beforeFieldRender</td><td>定义页面渲染前执行的逻辑，动态获取商机金额字段值并设置应用相应样式</td><td>beforeFieldRender: (e) =&gt; { ... }</td></tr><tr><td>设置字段值样式</td><td>样式扩展</td><td>属性：valueStyle</td><td>设置字段值颜色</td><td>valueStyle={color: &#39;orange&#39;}</td></tr></tbody></table><h2 id="使用的其他能力" tabindex="-1">使用的其他能力 <a class="header-anchor" href="#使用的其他能力" aria-label="Permalink to &quot;使用的其他能力&quot;">​</a></h2><p>无</p>',11)])])}const u=e(r,[["render",i]]);export{c as __pageData,u as default};
